describe('Alert Dialog Blocking Page Interaction', () => {
  beforeEach(() => {
    cy.visit('/alert-dialog');
  });

  it('should display alert dialog and block interaction with page behind it', () => {
    // Verify page is visible before dialog appears
    cy.get('[data-testid="page-content"]').should('be.visible');
    cy.get('[data-testid="page-content"]').should('contain', 'Page Content');

    // Click button to trigger alert dialog
    cy.get('[data-testid="open-alert-button"]').click();

    // Verify alert dialog is visible
    cy.get('[data-testid="alert-dialog"]').should('be.visible');
    cy.get('[data-testid="alert-title"]').should('contain', 'Alert');
    cy.get('[data-testid="alert-message"]').should('contain', 'This is an alert');

    // Verify page content is obscured by dialog overlay
    cy.get('[data-testid="page-content"]').should('have.css', 'pointer-events', 'none');

    // Verify dialog has close button
    cy.get('[data-testid="close-alert-button"]').should('be.visible');

    // Verify page content is not clickable while dialog is open
    cy.get('[data-testid="page-content"]').should('not.be.clickable');

    // Close the alert dialog
    cy.get('[data-testid="close-alert-button"]').click();

    // Verify dialog is no longer visible
    cy.get('[data-testid="alert-dialog"]').should('not.exist');

    // Verify page content is now interactive again
    cy.get('[data-testid="page-content"]').should('be.visible');
    cy.get('[data-testid="page-content"]').should('be.clickable');
  });

  it('should prevent interaction with page when alert dialog is open and focus is trapped', () => {
    // Trigger alert dialog
    cy.get('[data-testid="open-alert-button"]').click();

    // Verify alert dialog is visible
    cy.get('[data-testid="alert-dialog"]').should('be.visible');

    // Attempt to interact with page content while dialog is open
    cy.get('[data-testid="page-content"]').click({ force: true });

    // Verify page content was not interacted with (no navigation or state change)
    cy.get('[data-testid="page-content"]').should('contain', 'Page Content');

    // Verify focus is trapped within the alert dialog
    cy.get('[data-testid="alert-dialog"]').should('have.focus');

    // Verify close button is the only interactive element
    cy.get('[data-testid="close-alert-button"]').should('be.visible');
    cy.get('[data-testid="alert-title"]').should('be.visible');

    // Close the alert dialog
    cy.get('[data-testid="close-alert-button"]').click();

    // Verify dialog is closed
    cy.get('[data-testid="alert-dialog"]').should('not.exist');
  });
});
